import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"家人","description":"高島易斷 - 家人","frontmatter":{"title":"家人","description":"高島易斷 - 家人"},"headers":[],"relativePath":"classics/takashima/037.md","filePath":"classics/takashima/037.md"}'),i={name:"classics/takashima/037.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="家人" tabindex="-1">家人 <a class="header-anchor" href="#家人" aria-label="Permalink to “家人”">​</a></h1><h2 id="家人-1" tabindex="-1">家人 <a class="header-anchor" href="#家人-1" aria-label="Permalink to “家人”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>家人：利女貞。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>利貞兩字，為《家人》一卦中關鍵。自古家道之成敗，罔不由婦人始也，蓋賢婦則稱內助，淑女乃能宜家，賢而淑，則貞也，否則“牝雞司晨，惟家之索”，是宜戒也。《易》之全經，《上經》首《乾》《坤》，《乾》為父，《坤》為母，是謂老夫婦，卦備四德，而不專在利貞；《下經》首《鹹》《恆》，《鹹》為婦道之始，《恆》為婦道之終。《鹹》《彖》曰“利貞，娶女吉”，《恆》《彖》曰“利貞，無咎”，則知“從一而終”，“婦人貞吉”。《恆》五爻辭，顯揭《家人》一卦之旨，蓋貞則吉，不貞即不吉；《家人》卦德，專重夫貞，貞之吉象，專屬於女，故《家人》《彖》首揭之曰：“利女貞。”</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>風自火出，家人。君子以言有物而行有恆。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>《巽》為風，《離》為火，《巽》位在巳，《離》位在午，巳午皆火，故有“風自火出”之象。按《康成別傳》，見大風起，詣縣曰：某日當有火災，宜廣設禁備。至時，果有火起。《左傳》所謂“融風，火之始也”，即“為風自火出”之徵。且風之發也，瞬息而遍及，火之起也，傳燃而不盡，喻言教化之行，自內及外，其機甚捷，故曰“風自火出，家人”。考《洪範》五行，火以配言，《小畜》諸卦，風皆曰行，故君子取象於風火，以為言行。“物”，事也，“恆”，常也，火附物而生光，“言有物”而可則，風得《恆》而不易，“行有恆”而化成。言行君子之樞機，風火天地之噓氣，發邇見遠，其道相同。夫閨門之內，以恩掩義，以情奪禮，所恃以懾伏《家人》者，惟賴此言行而已。教化自言行出，言行又必自誠心出，誠則足以化人，不誠則自適以階厲，君子處家，故於言行尤兢兢焉。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：風得火而愈狂，火得風而益熾，正是時運全盛之會，然入邪則邪，入善則善，言行之間，最宜加勉。</p><p>○　問營商：《爾雅》雲：“風與火為庉”，“庉”，聚也，有屯聚貨物之象。爻辭曰“有物”“有恆”，物，貨物，恆，恆久，謂其物不容急售，過後可獲高價。</p><p>○　問功名：風行遠，火炎上，有高升遠到之象；言行者，出身加民之具，功名可必。</p><p>○　問家宅：防有火災。</p><p>○　問婚姻：《家人》一卦，象取夫婦，《離》火《巽》風皆女，或長女為姊，中女為娣之象，或為兩姓對結之親。吉。</p><p>○　問疾病：是風火上升，痰多氣喘之症，一時不治。</p><p>○　問六甲：生女。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>“閒”字，從門，從木，門內加木，所以防外也，故訓為防。《易·文言》曰閒邪存誠，謂防閒其邪念，《論語》曰“大德不逾閒”，閒闌也，謂闌止其出入，皆取禁止防範之意。初爻處下卦之首，為《家人》之始。“有家”者，孟子謂“女有家”，是專指女子而言；“閒”者，如閨有範，女有箴，皆所以教誡之也。為女之始，先立其閒，使知所謹守，而不敢隕越，猶如蒙之必先養正也。若家瀆而後嚴之，志變而後治之，則有悔矣。《象傳》曰“志未變也”，謂其心志本明，未即邪欲，閒之於初，悔自亡也。</p><h2 id="初九佔" tabindex="-1">初九佔 <a class="header-anchor" href="#初九佔" aria-label="Permalink to “初九佔”">​</a></h2><p>○　問時運：目下好運初來，正當自知檢束，斯無災悔。</p><p>○　問戰徵：當行軍之始，正宜整其步伐，嚴其號令，得以有勝無敗。</p><p>○　問營商：是初次販運，宜恪守商規。</p><p>○　問功名：是初次求名。宜遵公令，不得妄意幹進。</p><p>○　問家宅：此宅牆圍堅固，門戶肅睦，治家者有條有則，約束詳明。至四年後，可致饒富。吉。</p><p>○　問疾病：病是初起，宜自謹慎保養，必無災害。初若不治，必致變症，則難治矣。</p><p>○　問婚姻：當初訂姻好，知是家風清白，閨門素謹，可成。</p><p>○　問訟事：初訟罷之，則吉。</p><p>○　問六甲：是初胎，生女。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>二十三年十二月，友人某來，請佔商法成否，筮得《家人》之《漸》。</p><p>斷曰：風著物而鳴，火著物而燃，是風火皆虛，必託於物而成形，猶商業必藉資本而成事。今佔問商業，而得初爻，初者，為商業謀辦之始。我國自鎖港以前，外商未通，一切商人，皆守舊習，未能遠行，是以有悔。近始與各國貿易，所當先定商規，熟識行商之利益，猶是女子初嫁，當先學閨範，能諳為婦之禮教。為婦之道，在正家，為商之利，在裕國，其義一也。若不習之於初，而茫然從事，何能獲利乎？爻辭謂“閒有家，悔亡”，家之有閒，謹其出入，商之有閒，慎其出納，能守其閒，自有吉無悔矣。《象傳》曰“志未變也”，為通商伊始，陋習猶未變也。商法必成而有大用焉。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>“無攸遂”者，謂婦道無成，事無專制也。二至四互《坎》，《坎》為酒食，故曰“在中饋”，謂朝夕以治饔飧，婦人之職也。二爻在婦妻之位，備中正之德，應九五《離》明之主，是能柔順得正，以從事九五中正之夫者也。蓋婦人之道，惟在奉祭祀、饋飲食而已，不得干預外事。《採蘋》、《采蘩》兩篇，皆美其能誠奉祭祀，可知婦職專在中饋，《禮》所謂“奉箕帚，操井臼”者是也。《彖傳》曰“女正位乎內”，即指此爻。《象傳》曰“順以巽也”，按《象傳》稱“順以《巽》”者有三：《蒙》之六五，謂事《師》之道；《漸》之六四，謂事君之道；此爻謂事夫之道。即孟子所云“以順為正，妾婦之道”也。</p><h2 id="六二佔" tabindex="-1">六二佔 <a class="header-anchor" href="#六二佔" aria-label="Permalink to “六二佔”">​</a></h2><p>○　問時運：目下正當大運，但爻象重陰，只宜因人成事，不能獨斷獨行。</p><p>○　問戰徵：此是偏將，必非主師，或是後營，主管糧食軍餉，最為緊要，謹防勿失。</p><p>○　問營商：想是販運糧食生意，吉。</p><p>○　問功名：難以遂意。</p><p>○　問家宅：此宅朝南，宅主必是婦人，家事不能專斷，惟灶基最吉。</p><p>○　問疾病：幸胃口強健，可以無害。</p><p>○　問六甲：生女。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>某縉紳來，請佔氣運，筮得《家人》之《小畜》。</p><p>斷曰：二爻處下卦之中，為《離》之主，《離》象中虛，權無專制；《離》取鼎養，職在調羹。爻體以順，爻象屬陰，故只宜在內，而不在外也。今佔氣運，得《家人》二爻，知足下氣運平順，但才力柔弱，未得獨擅大權。只可奉公從事，或者授職宮內省，正所優為也。吉。</p><p>明治三十年，佔遞信省氣運，筮得《家人》之《小畜》。</p><p>斷曰：風火《家人》，風取其疾，火取其速，皆言來往迅速也。輪船鐵道，亦皆取力風火，則知卦象所云，正與遞信局事，大旨相合。《家人》二爻，爻辭曰“無攸遂，在中饋，貞吉”，“無攸遂”者，謂遞信，皆代人傳送信物而已；“在中饋”者，謂郵函報告，鐵道販運，惟以糧食為重也。其事行諸國中，達諸海外，正內正外，亦猶是也，故曰“貞吉”。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>“嗃”，《廣韻》，“嚴厲貌”；《玉篇》，“嚴大聲”。嗃從口，從高，謂大其聲使人畏憚也。“嘻嘻”，《玉篇》，“和樂聲”；嘻從口，從喜，謂和其聲使人喜悅也。九三以陽居陰，處下卦之極，為一家之主，剛嚴過甚，過嚴則傷恩，未免有厲，是嗃嗃之過也；若嘻嘻則和樂無度，過和則害義，終必見吝。蓋治家之道，嚴雖過其中，而要之家庭肅睦，鹹知敬畏，自不即於非禮，故曰“厲，吉”；和則雖上下歡悅，而荒淫佚樂，流弊有不可勝言者矣，故曰“終吝”。《象傳》以失不失對勘，謂和而終吝，不如厲而得吉也。</p><h2 id="九三佔" tabindex="-1">九三佔 <a class="header-anchor" href="#九三佔" aria-label="Permalink to “九三佔”">​</a></h2><p>○　問時運：運限平平，終貴自勉，嚴謹刻苦，不自憚勞，當必獲吉。若一味取樂，百事無成。</p><p>○　問戰徵：號令嚴明，萬軍畏服，縱不免殺戮過甚之患，而所問自得成功。</p><p>○　問營商：想是外作商店，內作住家，內外齊肅，家政嚴，店規謹，乃能獲吉。否則，過和而流，將有名可問。</p><p>○　問功名：爻象專在宜家，功名尚緩。</p><p>○　問家宅：此宅家規嚴肅，吉。</p><p>○　問婚姻：九三之應在上九，曰“有孚”，知兩姓相從，吉。</p><p>○　問疾病：九三屬《離》為火，宜進涼劑，雖危得愈。</p><p>○　問失物：宜嚴急查問，可得，若寬緩則失矣。</p><p>○　問六甲：生女。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>某縉紳來，請佔氣運，筮得《家人》之《益》。</p><p>斷曰：九三以陽居陰，剛嚴者也，處下體之極，為一家之長，是以剛嚴而督率家政也。剛嚴未必無悔，然較和而流者，其得多矣。足下佔氣運，今得此爻，知足下稟氣剛強，一生處世，與卦象符合。足下職掌政務，悉以嚴厲治之，一時屬員，未免怨苦，而於一切政務，罔不整肅，自無疏忽紊亂之弊，可以允吉。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>《離》《巽》二卦，為二女，皆自《坤》生，《坤》為富，為財，又為戶，有“富家”之象。六四以陰居陰，處上卦之首，與初相應，初曰“閒有家”，蓋保家有法，克勤克勤，日積月累，‘至四面儼成富家也，故曰“富家，大吉”。《象傳》曰“順在位也”，二四皆為卦主。二爻“在中饋”，中饋掌烹飪，《離》之位也；四曰“順在位”，順，《巽》之位也。蓋婦以順從其夫，得以致富，自能不失其職位也。</p><h2 id="六四佔" tabindex="-1">六四佔 <a class="header-anchor" href="#六四佔" aria-label="Permalink to “六四佔”">​</a></h2><p>○　問時運：目下正當盛運，已富者克保其家，未富者即發其財，大吉之象。</p><p>○　問戰徵：國富兵強，糧餉充足，可進可退，吉無不利。</p><p>○　問營商：“利市三倍”，立致富饒，吉可知也。</p><p>○　問功名：官與財多相反，必須破財，乃可成名。</p><p>○　問家宅：必是巨室閥閱之家，大吉。</p><p>○　問訟事：財可通神，事無不了。</p><p>○　問疾病：必是身體肥胖，膏梁過度所致，藥之即愈。</p><p>○　問六甲：生女。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>近來餘與友人謀創一業，佔問成敗吉凶如何，筮得《家人》之《同人》。</p><p>斷曰：我與友人謀事，則內卦《離》屬我，外卦《巽》屬友，《離》《巽》方位相同，可知我與友意氣相合；二四為內外卦主，可知我與友，亦各主一職，合以成事。今佔得六四，四居《巽》位，《巽》為商，為利，取象於“巽，近利市三倍”，利得三倍，即可致富。此商家中大吉象也，故爻辭曰“富家，大吉”。得此佔辭，決計立業，果得吉利。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>九五王位，王者以天下為一家，故推極言之。“假”與格同，謂感格也。五爻剛健中正，位居至尊，與六四相比，與六二相應，四以順在位，二以順相從，順則情性相通，纏綿固結，交相愛悅，假之所由來也。一家之中，父子兄弟夫婦，情意如一，王者家大人眾，推之天下，無不各長其長，各幼其幼，所謂“王假有家”，假之至矣。“勿恤，吉”者，謂王者感化之神，勿用憂恤，而自無不吉也。蓋初爻曰“閒有家”，以法度閒之，為家道之始；至五曰“王假有家”，假即假其閒家之善。王有家，是化家為國，化國為天下，為王者之家，家道之終也。一說假，大也。取“假哉天命”，謂大哉天命之義。“王假有家”，謂王者大，居正，故曰《大有》家。較四之富家而更進矣，其說亦通。</p><h2 id="九五佔" tabindex="-1">九五佔 <a class="header-anchor" href="#九五佔" aria-label="Permalink to “九五佔”">​</a></h2><p>○　問時運：運來福至，人心自然感通，何憂不吉？</p><p>○　問戰徵：王者之師，所向無敵。吉。</p><p>○　問營商：想此商業，必是奉公謀辦，或是貢獻品物，為王家之業也，吉。</p><p>○　問功名：恰如渭水付巖，有夢卜感通之象，吉。</p><p>○　問家宅：此宅想是公卿巨邸，吉。</p><p>○　問疾病：人身以心為君，五居《巽》木，必是肝木太強生風，心火生熱。藥宜熄火定風，使心氣開通，可勿憂也。吉。</p><p>○　問婚姻：有選入宮闈之象。</p><p>○　問六甲：生女。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>友人某來，請佔氣運，筮得《家人》之《賁》。</p><p>斷曰：人生作事，全憑氣運，運苟不佳，不特事多掣肘，即一家中，父子兄弟夫婦，亦不見信，如蘇秦不第歸來，嫂不下機，妻不執炊是也。氣運一通，不特下民信服，且有夢通良弼，卜兆非熊，忽來王朝之徵聘者，是皆運為之也。今佔得五爻，五居尊位，故稱“王”，“假”，格也，“勿恤”，勿憂也。知足下大運當盛，才志亦強，一年半載中，必有使命下頒，就家起用。五與二相應，二曰“中饋”，饋食也，祭也，或為祠官主祭祀，或奉公採辦糧餉，不須憂恤，自能得吉。足下可拭目待之！</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>上九居《巽》位之極，《巽》二陽一陰，上得乾氣，《乾》為信，故“有孚”。《乾》又為威，故“威如”，且《巽》風善入，有威孚之義。離火可畏，有威嚴之象。合上下兩體以成其爻，示人可因象以求義也。上與三應，三之“嘻嘻”，和而失節；上之“有孚”，則和順而能感人也。三之“嗃嗃”，嚴近於厲；上之“威如”，則嚴正而若可望也。蓋上為卦之終，教家之道，亦至上而成，故“終吉”。夫所謂正家者，其道不自家始也，家之本在身，先正其身，而家無不齊矣。君子不言而信，不怒而威，亦以誠之道感通之耳。《象傳》曰“反身”，即《大學》所謂齊其家，在修其身之旨也。</p><h2 id="上九佔" tabindex="-1">上九佔 <a class="header-anchor" href="#上九佔" aria-label="Permalink to “上九佔”">​</a></h2><p>○　問時運：得人信服，得人敬畏，事無不成，往無不利，可行於近，亦可行於遠，萬事皆吉。十年好運，過此而終。</p><p>○　問戰徵：行車之道，有信則人不我欺，有威則人不我狎，賞罰無私，號令必行，王者之師也，故吉。</p><p>○　問營商：有信則萬金可託，有威則百務皆修，商道之正也。</p><p>○　問功名：上爻處極位之地，必是身居上位，信義早孚，威望素著之大人也。</p><p>○　問家宅：此宅地位必高，為一鄉之望也。吉。</p><p>○　問婚姻：兩姓允從，吉。</p><p>○　問六甲：生女。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>明治二十年，佔某貴顯氣運，筮得《家人》之《既濟》。</p><p>斷曰：爻居上位，適合貴顯之象。爻辭曰“孚”，曰“威”，知威孚遍通夫上下，威望夙著於朝廷，所謂不言而信，不怒而威，為能得夫君子之道也，吉何如也！《彖傳》曰“正家而天下定”，貴顯有焉。《象》曰“反身之謂”，國之本在家，家之本在身，貴顯必能身修而家齊也。氣運之吉，不言可知。</p>',104)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
